From 50c9f40914eeb74b433b467f0da632396bcaf73b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 04:06:26 +0100
Subject: [PATCH] kded: don't notify when the user disconnects a connection

Disconnecting a network or VPN from the applet showed a "Connection
deactivated" notification, telling the user about something they just
did. Use the reason NetworkManager gives and skip user disconnects.

BUG: 409774
---
 kded/notification.cpp | 19 +++++++++++--------
 kded/notification.h   |  2 +-
 2 files changed, 12 insertions(+), 9 deletions(-)

diff --git a/kded/notification.cpp b/kded/notification.cpp
index 217998364..4f97923ae 100644
--- a/kded/notification.cpp
+++ b/kded/notification.cpp
@@ -313,11 +313,11 @@ void Notification::addActiveConnection(const NetworkManager::ActiveConnection::P
                && ac->type() != NetworkManager::ConnectionSettings::Team //
                && ac->type() != NetworkManager::ConnectionSettings::Vlan //
                && ac->type() != NetworkManager::ConnectionSettings::Tun) {
-        connect(ac.data(), &NetworkManager::ActiveConnection::stateChanged, this, &Notification::onActiveConnectionStateChanged);
+        connect(ac.data(), &NetworkManager::ActiveConnection::stateChangedReason, this, &Notification::onActiveConnectionStateChanged);
     }
 }

-void Notification::onActiveConnectionStateChanged(NetworkManager::ActiveConnection::State state)
+void Notification::onActiveConnectionStateChanged(NetworkManager::ActiveConnection::State state, NetworkManager::ActiveConnection::Reason reason)
 {
     auto ac = qobject_cast<NetworkManager::ActiveConnection *>(sender());

@@ -373,6 +373,11 @@ void Notification::onActiveConnectionStateChanged(NetworkManager::ActiveConnecti
             return;
         }

+        if (reason == NetworkManager::ActiveConnection::UserDisconnected) {
+            qCDebug(PLASMA_NM_KDED_LOG) << "Not emitting connection deactivated notification as the user disconnected it";
+            return;
+        }
+
         eventId = QStringLiteral("ConnectionDeactivated");
         text = i18n("Connection '%1' deactivated.", acName);

@@ -438,6 +443,10 @@ void Notification::onVpnConnectionStateChanged(NetworkManager::VpnConnection::St
         eventId = QStringLiteral("FailedToActivateConnection");
         text = i18n("VPN connection '%1' failed to activate.", vpnName);
     } else if (state == NetworkManager::VpnConnection::Disconnected) {
+        if (reason == NetworkManager::VpnConnection::UserDisconnectedReason) {
+            qCDebug(PLASMA_NM_KDED_LOG) << "Not emitting VPN connection deactivated notification as the user disconnected it";
+            return;
+        }
         eventId = QStringLiteral("ConnectionDeactivated");
         text = i18n("VPN connection '%1' deactivated.", vpnName);
     } else if (state == NetworkManager::VpnConnection::NeedAuth) {
@@ -448,9 +457,6 @@ void Notification::onVpnConnectionStateChanged(NetworkManager::VpnConnection::St
     }

     switch (reason) {
-    case NetworkManager::VpnConnection::UserDisconnectedReason:
-        text = i18n("VPN connection '%1' deactivated.", vpnName);
-        break;
     case NetworkManager::VpnConnection::DeviceDisconnectedReason:
         text = i18n("VPN connection '%1' was deactivated because the device it was using was disconnected.", vpnName);
         break;
@@ -494,9 +500,6 @@ void Notification::onVpnConnectionStateChanged(NetworkManager::VpnConnection::St
     notify->setComponentName(QStringLiteral("networkmanagement"));
     if (state == NetworkManager::VpnConnection::Activated) {
         notify->setIconName(QStringLiteral("dialog-information"));
-    } else if (state == NetworkManager::VpnConnection::Disconnected && reason == NetworkManager::VpnConnection::UserDisconnectedReason) {
-        // Don't show warning icon if the user explicitly disconnected
-        notify->setIconName(QStringLiteral("dialog-information"));
     } else {
         notify->setIconName(QStringLiteral("dialog-warning"));
     }
diff --git a/kded/notification.h b/kded/notification.h
index f9afb1268..6d82196dc 100644
--- a/kded/notification.h
+++ b/kded/notification.h
@@ -34,7 +34,7 @@ private Q_SLOTS:

     void addActiveConnection(const QString &path);
     void addActiveConnection(const NetworkManager::ActiveConnection::Ptr &ac);
-    void onActiveConnectionStateChanged(NetworkManager::ActiveConnection::State state);
+    void onActiveConnectionStateChanged(NetworkManager::ActiveConnection::State state, NetworkManager::ActiveConnection::Reason reason);
     void onVpnConnectionStateChanged(NetworkManager::VpnConnection::State state, NetworkManager::VpnConnection::StateChangeReason reason);

     void notificationClosed();
-- 
